    results = apis.spotify.search_songs(query=query, page_limit=20, access_token=spotify_access_token)
    found = False
    for result in results:
        # Check if any artist matches
        for artist in result["artists"]:
            if artist["name"] == song["artist_name"] and result["title"] == song["song_name"]:
                archive_song_ids.append(result["song_id"])
